// script.js - Main application logic and form handling

// Form elements
const form = document.getElementById('calc-form');

// Event listener
form.addEventListener('submit', handleFormSubmit);

/**
 * Handle form submission
 * @param {event} e - Form submit event
 */
function handleFormSubmit(e) {
    e.preventDefault();

    // Get input values
    const outstanding = parseFloat(document.getElementById('outstanding').value);
    const annualRate = parseFloat(document.getElementById('rate').value);
    const minPaymentPercent = parseFloat(document.getElementById('min-payment').value);
    const extraPayment = parseFloat(document.getElementById('extra-payment').value) || 0;

    // Validate inputs
    if (!validateInputs(outstanding, annualRate, minPaymentPercent)) {
        showError('Please enter valid values (positive numbers only)');
        return;
    }

    // Show loading
    showLoading();

    // Simulate calculation (setTimeout for smooth UX)
    setTimeout(() => {
        try {
            // Perform calculations
            const results = simulateDebtPayoff(outstanding, annualRate, minPaymentPercent, extraPayment);

            // Display results
            displayResults(results, outstanding, annualRate, minPaymentPercent, extraPayment);

            // Display insights
            const insights = generateEnhancedInsights(results, outstanding, annualRate, minPaymentPercent, extraPayment);
            displayInsights(insights);

            // Scroll to results
            document.getElementById('results').scrollIntoView({ behavior: 'smooth' });

            hideLoading();
        } catch (error) {
            showError('Calculation error: ' + error.message);
            hideLoading();
        }
    }, 300);
}

/**
 * Validate form inputs
 * @param {number} outstanding - Outstanding amount
 * @param {number} rate - Interest rate
 * @param {number} minPayment - Minimum payment
 * @returns {boolean} Valid or not
 */
function validateInputs(outstanding, rate, minPayment) {
    if (isNaN(outstanding) || outstanding <= 0) return false;
    if (isNaN(rate) || rate < 0 || rate > 100) return false;
    if (isNaN(minPayment) || minPayment <= 0 || minPayment > 100) return false;
    return true;
}

/**
 * Show error message
 * @param {string} message - Error message
 */
function showError(message) {
    alert(message); // In production, use a toast notification
}

/**
 * Show loading message
 */
function showLoading() {
    const resultsDiv = document.getElementById('results');
    resultsDiv.innerHTML = '<p>Calculating...</p>';
}

/**
 * Hide loading message
 */
function hideLoading() {
    // Loading is replaced by results
}

/**
 * Simulate debt payoff and generate amortization schedule
 * @param {number} outstanding - Initial outstanding amount
 * @param {number} annualRate - Annual interest rate (%)
 * @param {number} minPaymentPercent - Minimum payment percentage (%)
 * @param {number} extraPayment - Extra payment amount
 * @returns {Array} Array of monthly data objects
 */
function simulateDebtPayoff(outstanding, annualRate, minPaymentPercent, extraPayment) {
    const schedule = [];
    let balance = outstanding;
    let month = 0;
    const monthlyRate = annualRate / 12 / 100;

    while (balance > 0 && month < 1000) { // Prevent infinite loop
        month++;
        const interest = balance * monthlyRate;
        const minPayment = balance * minPaymentPercent / 100;
        const totalPayment = Math.min(minPayment + extraPayment, balance + interest); // Can't pay more than balance + interest
        const principal = totalPayment - interest;
        const newBalance = balance - principal;

        schedule.push({
            month,
            emi: totalPayment,
            principal,
            interest,
            balance: newBalance > 0 ? newBalance : 0
        });

        balance = newBalance;
        if (balance <= 0) break;
    }

    return schedule;
}

/**
 * Display results including amortization schedule
 * @param {Array} schedule - Amortization schedule
 * @param {number} outstanding - Initial outstanding
 * @param {number} annualRate - Annual rate
 * @param {number} minPaymentPercent - Min payment %
 * @param {number} extraPayment - Extra payment
 */
function displayResults(schedule, outstanding, annualRate, minPaymentPercent, extraPayment) {
    const resultsDiv = document.getElementById('results');
    let html = `<h2>Debt Payoff Summary</h2>`;
    html += `<p>Total Months: ${schedule.length}</p>`;
    html += `<p>Total Interest Paid: ₹${schedule.reduce((sum, row) => sum + row.interest, 0).toFixed(2)}</p>`;
    html += `<p>Total Payments: ₹${schedule.reduce((sum, row) => sum + row.emi, 0).toFixed(2)}</p>`;

    // Amortization Schedule Table
    html += `<h3>Amortization Schedule</h3>`;
    html += `<div class="table-container">`;
    html += `<table id="amortizationTable">`;
    html += `<thead><tr><th>Month</th><th>EMI (₹)</th><th>Principal (₹)</th><th>Interest (₹)</th><th>Balance (₹)</th></tr></thead>`;
    html += `<tbody id="amortizationBody">`;

    schedule.forEach(row => {
        html += `<tr>
            <td>${row.month}</td>
            <td>${row.emi.toFixed(2)}</td>
            <td>${row.principal.toFixed(2)}</td>
            <td>${row.interest.toFixed(2)}</td>
            <td>${row.balance.toFixed(2)}</td>
        </tr>`;
    });

    html += `</tbody></table></div>`;

    resultsDiv.innerHTML = html;
}

/**
 * Generate enhanced insights
 * @param {Array} schedule - Schedule
 * @param {number} outstanding - Outstanding
 * @param {number} annualRate - Rate
 * @param {number} minPaymentPercent - Min %
 * @param {number} extraPayment - Extra
 * @returns {string} Insights HTML
 */
function generateEnhancedInsights(schedule, outstanding, annualRate, minPaymentPercent, extraPayment) {
    // Placeholder for insights
    return `<h3>Insights</h3><p>Payoff completed in ${schedule.length} months.</p>`;
}

/**
 * Display insights
 * @param {string} insights - Insights HTML
 */
function displayInsights(insights) {
    const insightsDiv = document.getElementById('insights');
    if (insightsDiv) {
        insightsDiv.innerHTML = insights;
    }
}

